132	- [ ] **Task 6: Frontend — `BuchungDetailPage`: GET-Fallback, `justBooked`-Flag, Ladezustand** (AC: #1, #3)
133	  - [ ] `features/buchung/buchung-detail-page/buchung-detail-page.ts` — bestehende Component umbauen. Bisher (Story 2.5) wurde `booking`/`justBooked` **ausschließlich** aus dem Router-Navigationsstate gelesen (`computed()`, siehe Story-2.5-Dev-Notes "Standalone-Epic-Grenze zu Epic 3" — dieser GET-Fallback ist genau die dort angekündigte Ergänzung). Neue Struktur: Navigationsstate bleibt die bevorzugte, sofortige Quelle (kein Re-Fetch nötig, wenn die Daten schon da sind); fehlt er (Reload/Bookmark/Direktaufruf **oder** Ankunft von der neuen `BuchungAbrufenPage`, Task 7), wird per `GET` nachgeladen:
134	    ```ts
135	    import { DatePipe } from '@angular/common';
136	    import { Component, computed, effect, inject, input, signal } from '@angular/core';
137	    import { Router } from '@angular/router';
138	
139	    import { Booking } from '../../../core/models/booking.model';
140	    import { BookingService } from '../../../core/services/booking.service';
141	    import { formatEuroAmount } from '../../../shared/format-currency';
142	
143	    @Component({
144	      selector: 'app-buchung-detail-page',
145	      imports: [DatePipe],
146	      templateUrl: './buchung-detail-page.html',
147	      styleUrl: './buchung-detail-page.scss'
148	    })
149	    export class BuchungDetailPage {
150	      private readonly router = inject(Router);
151	      private readonly bookingService = inject(BookingService);
152	
153	      readonly referenz = input.required<string>();
154	
155	      // Lazy computed() statt eagerly initialisiertem signal(): referenz() ist erst nach
156	      // Konstruktion gesetzt (Router-Input-Binding) — siehe Story 2.5 Dev Agent Record
157	      // (NG0950-Bugfix), unverändert übernommenes Muster.
158	      private readonly navigationState = computed(() => {
159	        const state = this.router.getCurrentNavigation()?.extras.state ?? history.state;
160	        const typed = state as { booking?: Booking; justBooked?: boolean } | undefined;
161	        return typed?.booking && typed.booking.reference === this.referenz()
162	          ? { booking: typed.booking, justBooked: typed.justBooked === true }
163	          : null;
164	      });
165	
166	      private readonly fetchedBooking = signal<Booking | null>(null);
167	      protected readonly loadError = signal(false);
168	
169	      protected readonly booking = computed<Booking | null>(() => this.navigationState()?.booking ?? this.fetchedBooking());
170	      protected readonly justBooked = computed(() => this.navigationState()?.justBooked === true);
171	      protected readonly copied = signal(false);
172	
173	      protected readonly formatEuroAmount = formatEuroAmount;
174	
175	      constructor() {
176	        effect((onCleanup) => {
177	          if (this.navigationState()) {
178	            return;
179	          }
180	
181	          this.fetchedBooking.set(null);
182	          this.loadError.set(false);
183	
184	          const subscription = this.bookingService.getBooking(this.referenz()).subscribe({
185	            next: (booking) => this.fetchedBooking.set(booking),
186	            error: () => this.loadError.set(true)
187	          });
188	
189	          onCleanup(() => subscription.unsubscribe());
190	        });
191	      }
192	
193	      protected copyReference(): void {
194	        navigator.clipboard.writeText(this.referenz()).then(() => {
195	          this.copied.set(true);
196	          setTimeout(() => this.copied.set(false), 2000);
197	        });
198	      }
199	    }
200	    ```
