import { Component, computed, inject, input, signal } from '@angular/core';
import { Router } from '@angular/router';

import { Booking } from '../../../core/models/booking.model';
import { formatEuroAmount } from '../../../shared/format-currency';

@Component({
  selector: 'app-buchung-detail-page',
  imports: [],
  templateUrl: './buchung-detail-page.html',
  styleUrl: './buchung-detail-page.scss'
})
export class BuchungDetailPage {
  private readonly router = inject(Router);

  readonly referenz = input.required<string>();

  // Lazy computed() statt eines eagerly initialisierten signal(): das required-Input
  // `referenz` ist erst nach Konstruktion gesetzt (Router-Input-Binding), ein Zugriff im
  // Field-Initializer würde NG0950 auslösen. computed() wertet erst beim ersten Lesen aus.
  protected readonly booking = computed<Booking | null>(() => this.readBookingFromNavigationState());
  protected readonly justBooked = computed(() => this.booking() !== null);
  protected readonly copied = signal(false);

  protected readonly formatEuroAmount = formatEuroAmount;

  private readBookingFromNavigationState(): Booking | null {
    const state = this.router.getCurrentNavigation()?.extras.state ?? history.state;
    const booking = (state as { booking?: Booking } | undefined)?.booking;
    return booking && booking.reference === this.referenz() ? booking : null;
  }

  protected copyReference(): void {
    navigator.clipboard.writeText(this.referenz()).then(() => {
      this.copied.set(true);
      setTimeout(() => this.copied.set(false), 2000);
    });
  }
}

