@if (booking(); as b) {
  @if (justBooked()) {
    <p class="buchung-detail-page__confirmation">Buchung bestätigt.</p>
  }
  <p class="buchung-detail-page__event">{{ b.eventTitle }} · {{ b.venueName }} · {{ b.startsAt | date: 'dd.MM.yyyy, HH:mm' }}</p>
  <div class="buchung-detail-page__reference" aria-label="Buchungsreferenz">
    <span>{{ referenz() }}</span>
    <button type="button" (click)="copyReference()">{{ copied() ? 'Kopiert.' : 'Kopieren' }}</button>
  </div>
  <ul class="buchung-detail-page__seats">
    @for (seat of b.seats; track seat.seatId) {
      <li>Reihe {{ seat.row }}, Platz {{ seat.column }} · {{ seat.priceCategoryName }} — {{ formatEuroAmount(seat.price) }}</li>
    }
  </ul>
  <p class="buchung-detail-page__total">Gesamtpreis: {{ formatEuroAmount(b.totalPrice) }}</p>
} @else if (loadError()) {
  <p role="alert">Keine Buchung mit dieser Referenz gefunden.</p>
} @else {
  <div class="buchung-detail-page__skeleton" aria-busy="true" aria-label="Buchung wird geladen">
    <div class="buchung-detail-page__skeleton-block buchung-detail-page__skeleton-block--reference"></div>
    <div class="buchung-detail-page__skeleton-block"></div>
    <div class="buchung-detail-page__skeleton-block"></div>
    <div class="buchung-detail-page__skeleton-block buchung-detail-page__skeleton-block--total"></div>
  </div>
}

